<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{{$vps->hostname?:('VPS #'.$vps->id)}} · Nodexa</title><style>:root{--bg:#061321;--panel:#0b1d2e;--panel2:#0e253a;--line:#183753;--blue:#5596ff;--text:#f5f8fc;--muted:#8298ab;--green:#43dca0;--red:#ff6577;--orange:#ffbd59}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 70% 0,#0b2843 0,transparent 32%),var(--bg);color:var(--text);font:14px Inter,system-ui,-apple-system,"Segoe UI",sans-serif}a{text-decoration:none;color:inherit}.top{height:72px;border-bottom:1px solid var(--line);background:rgba(6,19,33,.94)}.topin{max-width:1280px;height:100%;margin:auto;padding:0 22px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:11px;font-weight:850}.logo{width:35px;height:35px;border-radius:9px;background:linear-gradient(145deg,#5596ff,#306fd0);display:grid;place-items:center;font-weight:900}.brand small{display:block;color:#7790a5;font-size:8px;letter-spacing:1.4px;margin-top:2px}.back{font-size:11px;color:#9db1c2;padding:8px 10px;border-radius:7px}.wrap{max-width:1280px;margin:24px auto 70px;padding:0 22px}.hero{position:relative;overflow:hidden;display:flex;align-items:center;justify-content:space-between;gap:20px;background:linear-gradient(120deg,#0c2a43,#0a2034);border:1px solid #205078;border-radius:16px;padding:24px;margin-bottom:16px}.server-title{display:flex;align-items:center;gap:14px}.server-icon{width:45px;height:45px;border-radius:10px;background:rgba(85,150,255,.14);border:1px solid rgba(85,150,255,.2);display:grid;place-items:center;color:#79adff}.hero h1{font-size:21px;margin:0 0 5px}.meta,.note,.help{color:var(--muted);font-size:10px}.status{display:inline-flex;align-items:center;gap:6px;padding:6px 10px;border-radius:20px;background:rgba(67,220,160,.1);color:var(--green);font-size:10px;font-weight:800}.overview{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:16px}.stat,.card{background:linear-gradient(145deg,#0d2235,#091a29);border:1px solid var(--line);border-radius:11px}.stat{padding:14px 15px}.stat span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;margin-bottom:6px}.stat strong{font-size:13px}.content{display:grid;grid-template-columns:minmax(0,1.4fr) minmax(310px,.6fr);gap:16px}.card{overflow:hidden;margin-bottom:16px}.title{padding:14px 16px;border-bottom:1px solid var(--line);font-size:12px;font-weight:800;display:flex;justify-content:space-between}.body{padding:15px}.powers{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.btn{width:100%;border:1px solid transparent;border-radius:7px;padding:10px 12px;background:linear-gradient(135deg,var(--blue),#3479e4);color:#fff;font-size:11px;font-weight:800;cursor:pointer}.btn.secondary{background:#102a40;border-color:#244a69}.btn.green{background:#147d5d}.btn.orange{background:#966213}.btn.red{background:#a73f4d}.credentials{display:grid;grid-template-columns:.7fr 1.3fr;gap:9px}.credential,.auto-user{background:#091b2b;border:1px solid var(--line);border-radius:8px;padding:13px}.credential label,.auto-user label{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;margin-bottom:7px}.password-row{display:flex;gap:6px;align-items:center}.password-row code{flex:1;word-break:break-all}.mini{width:auto;padding:6px 8px;font-size:9px}.empty-password{font-size:10px;color:var(--muted);line-height:1.5}.field{width:100%;padding:10px;border:1px solid var(--line);background:#091b2b;color:#fff;border-radius:7px;margin:7px 0 11px}.danger{border-color:rgba(255,101,119,.25)}.danger .title{color:#ff9baa}.alert{padding:12px;border-radius:8px;margin-bottom:12px}.ok{color:var(--green)}.err{color:#ff9baa}.footer{text-align:center;color:#48657d;font-size:10px}@media(max-width:850px){.overview{grid-template-columns:1fr 1fr}.content{grid-template-columns:1fr}.powers{grid-template-columns:1fr 1fr}}@media(max-width:560px){.topin,.wrap{padding-left:14px;padding-right:14px}.brand small{display:none}.credentials{grid-template-columns:1fr}}</style></head><body><header class="top"><div class="topin"><a class="brand" href="/client"><span class="logo">N</span><span>Nodexa<small>HOSTING CLOUD</small></span></a><a class="back" href="/client#vps">← Client Area</a></div></header><main class="wrap">@if(session('success'))<div class="alert ok">{{session('success')}}</div>@endif @if($errors->any())<div class="alert err">{{$errors->first()}}</div>@endif @if($apiError)<div class="alert err">Flax API: {{$apiError}}</div>@endif @php($currentPassword=$storedPassword??($info['password']??$info['root_password']??$info['rootPassword']??$info['admin_password']??$info['adminPassword']??null)) @php($osDisplay=(string)($info['os_name']??$info['operatingSystem']??'')) @php($osCollection=collect($oses)) @php($selectedOs=$osCollection->first(function($os) use ($vps){return (string)($os['id']??$os['value']??$os['template_id']??'')===(string)$vps->os_id;})) @php($selectedOsName=is_array($selectedOs)?(string)($selectedOs['name']??$selectedOs['label']??$selectedOs['title']??''):'') @php($isWindows=stripos($osDisplay.' '.$selectedOsName,'windows')!==false) @php($currentUser=$isWindows?'Administrator':'root')<section class="hero"><div class="server-title"><div class="server-icon">◇</div><div><div class="meta">Nodexa VPS Control</div><h1>{{$vps->hostname?:('VPS #'.$vps->id)}}</h1><div class="meta">VPS #{{$vps->id}} · Flax server #{{$vps->provider_server_id?:'—'}}</div></div></div><span class="status">{{str_replace('_',' ',$vps->status)}}</span></section><section class="overview"><div class="stat"><span>IP-adresse</span><strong>{{$vps->ip_address?:($info['ip_address']??$info['ip']??'Afventer IP')}}</strong></div><div class="stat"><span>Operativsystem</span><strong>{{$info['os_name']??$info['operatingSystem']??($selectedOsName?:('OS ID '.($vps->os_id?:'—')))}}</strong></div><div class="stat"><span>Hostname</span><strong>{{$vps->hostname?:($info['hostname']??'—')}}</strong></div><div class="stat"><span>Status</span><strong>{{$info['status']??$vps->status}}</strong></div></section><div class="content"><div><section class="card"><div class="title"><span>Strømstyring</span><span class="help">Power controls</span></div><div class="body powers">@foreach(['boot'=>['▶ Start','green'],'shutdown'=>['■ Luk ned','orange'],'restart'=>['↻ Genstart',''],'poweroff'=>['⚠ Tving sluk','red']] as $action=>$x)<form method="POST" action="/client/vps/{{$vps->id}}/power">@csrf<input type="hidden" name="action" value="{{$action}}"><button class="btn {{$x[1]}}">{{$x[0]}}</button></form>@endforeach</div></section><section class="card"><div class="title"><span>Adgang til server</span><span class="help">SSH / Remote Desktop</span></div><div class="body credentials"><div class="credential"><label>Brugernavn</label><strong>{{$currentUser}}</strong></div><div class="credential"><label>Adgangskode</label>@if($currentPassword)<div class="password-row"><code id="vps-password" data-password="{{e($currentPassword)}}">••••••••••••</code><button type="button" class="btn mini secondary" onclick="togglePass(this)">Vis</button><button type="button" class="btn mini secondary" onclick="copyPass(this)">Kopiér</button></div>@else<div class="empty-password">Nodexa har ikke adgangskoden endnu. Nulstil den én gang for at gemme den krypteret.</div>@endif</div></div></section></div><aside><section class="card"><div class="title"><span>Nulstil adgangskode</span><span class="help">Security</span></div><form class="body" method="POST" action="/client/vps/{{$vps->id}}/reset-password">@csrf<div class="note">Nodexa vælger automatisk korrekt administratorkonto ud fra operativsystemet.</div><div class="auto-user" style="margin:11px 0"><label>Konto</label><strong>{{$currentUser}}</strong><div class="note" style="margin-top:5px">{{$isWindows?'Windows · Administrator':'Linux · root'}}</div></div><button class="btn">Nulstil adgangskode</button></form></section><section class="card danger"><div class="title">Geninstaller VPS</div><form class="body" method="POST" action="/client/vps/{{$vps->id}}/rebuild" onsubmit="return confirm('ADVARSEL: Alt data på VPS’en slettes permanent. Fortsæt?')">@csrf<div class="note"><strong style="color:#ff9baa">Advarsel:</strong> Geninstallation sletter alle filer og det gemte password.</div><select class="field" name="os_id" required><option value="">Vælg operativsystem...</option>@foreach($oses as $os) @php($oid=$os['id']??$os['value']??$os['template_id']??'') @php($on=$os['name']??$os['label']??$os['title']??('OS '.$oid))<option value="{{$oid}}" {{$oid==$vps->os_id?'selected':''}}>{{$on}}</option>@endforeach</select><input type="hidden" name="confirm" value="REINSTALL"><button class="btn red">Geninstaller VPS</button></form></section></aside></div><div class="footer">Nodexa VPS Control · Server #{{$vps->id}}</div></main><script>function togglePass(b){var e=document.getElementById('vps-password'),s=e.dataset.shown==='1';e.textContent=s?'••••••••••••':e.dataset.password;e.dataset.shown=s?'0':'1';b.textContent=s?'Vis':'Skjul'}function copyPass(b){navigator.clipboard.writeText(document.getElementById('vps-password').dataset.password);var t=b.textContent;b.textContent='Kopieret';setTimeout(function(){b.textContent=t},1200)}</script></body></html>